def transform(grid):
    from collections import deque
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            edge = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                edge |= y in (0, h - 1) or x in (0, w - 1)
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == background and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not edge:
                for y, x in comp:
                    grid[y][x] = 4
    return grid
